(() => {
  let active=null;
  function guardRoute(route){
    if(!active)return true;
    if(!active.page.isConnected){active=null;return true;}
    if(route===active.route)return true;
    if(active.allowLeave||!active.shouldBlock()){active=null;return true;}
    history.pushState(null,'',active.url);
    active.requestCancel();return false;
  }
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${{back:'<path d="m15 5-7 7 7 7"/>',copy:'<rect x="8" y="3" width="13" height="14" rx="2"/><path d="M16 17v4H3V7h5"/>',tap:'<path d="M9 12V5a2 2 0 0 1 4 0v6m0-3 3 1 3 2v7a4 4 0 0 1-4 4h-3l-6-7a2 2 0 0 1 3-3l2 2"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>'}[name]}</svg>`;
  const payload=o=>'upi://pay?'+new URLSearchParams({pa:o.recipientUpi||'7898163599@ybl',pn:o.recipientName||'Color Win',am:Number(o.amount).toFixed(2),cu:'INR',tr:o.number||o.id,tn:'Color Win deposit '+(o.number||o.id)}).toString();
  const badge=app=>app==='Paytm'?'<span class="checkout-paytm">pay<span>tm</span></span>':'<img class="checkout-phonepe" src="assets/payment-methods/phonepe.svg" alt="" aria-hidden="true">';
  const apps=(compact,bank)=>`<section class="checkout-apps"><h2>Choose a payment method to pay</h2><div class="checkout-app-options ${compact?'compact':''}">${['Paytm','PhonePe',...(bank?['PhonePe Bank (Bank Cards Only)']:[])].map(app=>`<button type="button" data-open-app="${esc(app)}">${compact?`<span class="checkout-app-brand">${badge(app)}<span>${app}</span></span><span class="checkout-app-watermark" aria-hidden="true">${badge(app)}</span>`:badge(app)+`<span>${app}</span>`+icon('tap')}</button>`).join('')}</div></section>`;
  const utr=dark=>`<section class="checkout-utr"><h2>${dark?'Input UTR / Paste UTR':'Paid? Submit UTR/Ref No'} ${dark?'':'<button type="button" id="utr-guide">ⓘ Guide</button>'}</h2>${dark?'<p class="checkout-warning">Please enter your UTR after a successful payment.</p>':''}<label class="checkout-utr-input">${dark?'':icon('card')+'<span>UTR</span>'}<input id="payment-utr" inputmode="numeric" maxlength="12" autocomplete="off" aria-label="12-digit UTR" placeholder="${dark?'Input 12 digits here':'UTR/UPI Ref No/UPI Transaction ID'}">${dark?'<button type="button" id="utr-paste">Paste</button>':''}</label>${dark?'':'<button type="button" id="utr-submit" disabled>Submit UTR/Ref No</button>'}<p id="utr-error" role="alert"></p></section>`;
  function view(order){if(!order)return '<main class="wallet-content"><p>Order not found in this browser session.</p><a href="#/deposit">Back to deposit</a></main>';
    const dark=order.method==='upi',umony=order.method==='innate',theme=dark?'upi':umony?'umony':'blue';
    const qr=`<div class="checkout-qr-section"><h2>${dark?'Use Mobile Scan code to pay':'Please fill in UTR after successful payment<br>Use Mobile Scan QR To Pay'}</h2><div class="checkout-qr-box"><div class="payment-qr-wrap"><div id="payment-qr" aria-label="UPI payment QR code"></div><div id="payment-expired" hidden>QR expired</div><div id="payment-success" class="checkout-payment-success" role="status" aria-live="polite" hidden><svg viewBox="0 0 96 96" aria-hidden="true"><circle class="payment-success-ring" cx="48" cy="48" r="42"/><path class="payment-success-check" d="m27 49 14 14 29-30"/></svg><strong>Payment successful</strong><span>₹${Number(order.amount).toFixed(2)}</span></div></div>${dark?'<p>1. Please use another device to scan the QR code with your payment app.</p><p>2. Your payment app may apply limits when scanning from this device’s gallery.</p>':''}</div>${dark?'':'<p class="checkout-warning">Do not save QR codes for repeated payments, or the funds may not be credited.</p>'}${theme==='blue'?'<button type="button" id="payment-save">Save</button>':''}</div>`;
    return `<div class="checkout checkout-${theme}"><header class="checkout-header"><a href="#/deposit" aria-label="Go back">${icon('back')}</a><h1>${dark?'Color Win':umony?'payment':'Payment'}</h1>${dark?'<a class="checkout-service" href="#/promotion/support">Customer Service</a>':theme==='blue'?'<strong id="payment-timer">10:00</strong>':'<span></span>'}</header><main class="checkout-main"><section class="checkout-payable">${dark?'':'<h2>Amount Payable</h2>'}<div><strong>₹${Number(order.amount).toFixed(2)}</strong>${dark?`<button type="button" id="payment-copy-amount" aria-label="Copy amount">${icon('copy')}</button><b id="payment-timer">10:00</b>`:''}</div>${umony?'<b id="payment-timer">10:00</b>':''}</section>${dark?apps(true,false):''}${qr}${dark?'':apps(false,theme==='blue')}${utr(dark)}${dark?'<section class="checkout-reminders"><h2>Important reminder:</h2><p>1. Do not pay for the same link repeatedly!</p><p>2. Enter the UTR only after transferring the money.</p></section>':umony?'<section class="checkout-notice"><h2>Notice:</h2><p>If you have any payment issues, contact <a href="#/promotion/support">Color Win customer service</a>.</p></section>':''}${dark?'<p id="payment-status" class="checkout-inline-status" role="status"></p>':`<section class="checkout-order"><p>Pay to ${esc(order.recipientName||'Color Win')} · ${esc(order.recipientUpi||'7898163599@ybl')}</p><div><span>${esc(order.number||order.id)}</span><button type="button" id="payment-copy" aria-label="Copy order number">${icon('copy')}</button></div><p id="payment-status" role="status">${order.status==='pending'?'UTR submitted. Pending payment verification.':order.status==='cancelled'?'This order was cancelled.':'Awaiting payment verification.'}</p><button type="button" id="payment-check">Check payment status</button>${dark?'':'<button type="button" id="payment-cancel">Cancel transaction</button>'}</section>`}</main>${dark?'<footer class="checkout-footer"><button type="button" id="payment-cancel">Cancel</button><button type="button" id="utr-submit" disabled>Submit (UTR not entered)</button></footer>':''}</div>`;
  }
  function dialog(page,content,className='checkout-dialog') {const d=document.createElement('dialog');d.className=className;d.innerHTML=content;page.append(d);d.addEventListener('close',()=>d.remove());d.onclick=e=>{if(e.target===d)d.close();};d.showModal();return d;}
  function maintenance(page,name='ARPay'){const d=dialog(page,`<h2>${esc(name)} maintenance</h2><p>${esc(name)} is temporarily under maintenance. ${name==='ARPay'?'Please choose another payment method.':'Please try again later.'}</p><button type="button" data-close>OK</button>`);d.querySelector('[data-close]').onclick=()=>d.close();}
  function bind(page,initial,{read,write,toast}) {if(!initial)return;let order=initial,submitting=false;const qr=page.querySelector('#payment-qr'),input=page.querySelector('#payment-utr'),submit=page.querySelector('#utr-submit'),status=page.querySelector('#payment-status');
    const current=()=>read().orders.find(o=>o.id===order.id);
    const isYoupi=order.gatewayProvider==='youpi';let gatewayReady=!isYoupi||!!initial.gatewayStatus,gatewayState=initial.gatewayStatus||'',queuePosition=initial.queuePosition||0,lastQr='';
    const stopped=()=>['pending','cancelled','complete','rejected'].includes(order.status)||(isYoupi?(!gatewayReady||gatewayState!=='ACTIVE'||Date.now()>=order.expiresAt):Date.now()>=order.expiresAt);
    const drawQr=()=>{const text=payload(order);if(text!==lastQr&&!stopped()){qr.innerHTML='';new QRCode(qr,{text,width:220,height:220,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});lastQr=text;}};
    const valid=()=>/^\d{12}$/.test(input.value)&&!stopped();
    const update=()=>{submit.disabled=!valid();if(order.method==='upi')submit.textContent=order.status==='pending'?'Submitted for verification':valid()?'Submit UTR':'Submit (UTR not entered)';};
    drawQr();
    let timer;const tick=()=>{if(!page.isConnected){clearInterval(timer);return;}order=current()||order;const complete=order.status==='complete';const waiting=isYoupi&&order.status==='to be paid'&&(!gatewayReady||gatewayState==='QUEUED');const seconds=waiting?0:Math.max(0,Math.ceil((order.expiresAt-Date.now())/1000));drawQr();page.querySelector('#payment-timer').textContent=waiting?'--:--':String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');const ended=stopped();qr.hidden=ended;const message=page.querySelector('#payment-expired');message.hidden=!ended||complete;const success=page.querySelector('#payment-success');success.hidden=!complete;page.querySelector('.checkout').classList.toggle('checkout-payment-complete',complete);if(complete){status.textContent='Payment successful';if(active?.page===page)active.allowLeave=true;}message.textContent=waiting?(gatewayReady?'Waiting for payment slot'+(queuePosition?' · '+queuePosition:''):'Loading payment QR…'):order.status==='complete'?'Payment successful':order.status==='pending'||gatewayState==='PROCESSING'?'Pending verification':order.status==='cancelled'?'Order cancelled':'QR expired';const check=page.querySelector('#payment-check');if(check)check.disabled=order.status==='cancelled'||(!seconds&&order.status!=='pending');page.querySelectorAll('[data-open-app],#payment-save').forEach(b=>b.disabled=ended);input.readOnly=ended;page.querySelector('#payment-cancel').disabled=['pending','cancelled','complete'].includes(order.status);if(!complete&&!waiting&&!seconds&&order.status==='to be paid')status.textContent='This QR has expired. Create a new deposit order.';update();if(ended&&!isYoupi)clearInterval(timer);};
    input.value=order.utr||'';input.oninput=()=>{input.value=input.value.replace(/\D/g,'').slice(0,12);page.querySelector('#utr-error').textContent='';update();};tick();if(isYoupi||!stopped())timer=setInterval(tick,1000);
    let refreshing=false;const refreshGateway=async()=>{if(!page.isConnected||refreshing)return;refreshing=true;try{const fresh=await window.ColorWinYoupi.state(order.id);if(!page.isConnected)return;gatewayReady=true;gatewayState=fresh.gatewayStatus;queuePosition=fresh.queuePosition;const state=read(),index=state.orders.findIndex(o=>o.id===fresh.id);if(index>=0){state.orders[index]=fresh;write(state);}order=fresh;status.textContent=fresh.status==='complete'?'Payment successful':fresh.status==='pending'?'UTR submitted. Pending payment verification.':gatewayState==='QUEUED'?'Preparing your payment QR. Please wait.':'';tick();}catch(err){status.textContent=gatewayReady?'Checking payment status… Your current QR is still valid until its timer ends.':err.message;tick();}finally{refreshing=false;}};
    if(isYoupi){refreshGateway();const poll=setInterval(()=>{if(!page.isConnected){clearInterval(poll);return;}if(!['complete','cancelled','rejected'].includes((current()||order).status))refreshGateway();else{tick();clearInterval(poll);}},5000);}
    page.querySelector('#payment-copy')?.addEventListener('click',()=>copy(order.number||order.id,toast));page.querySelector('#payment-copy-amount')?.addEventListener('click',()=>copy(Number(order.amount).toFixed(2),toast));page.querySelector('#payment-check')?.addEventListener('click',async()=>{try{await window.ColorWinOperations.loadWallet();order=current()||order;status.textContent='Payment status: '+order.status+(order.reviewNote?' · '+order.reviewNote:'');tick();}catch(err){toast(err.message,true);}});
    page.querySelector('#utr-paste')?.addEventListener('click',async()=>{if(stopped())return;try{const text=(await navigator.clipboard.readText()).trim();if(!/^\d{12}$/.test(text)){page.querySelector('#utr-error').textContent='Paste a valid 12-digit UTR.';return;}input.value=text;update();}catch{page.querySelector('#utr-error').textContent='Clipboard unavailable. Please enter the UTR manually.';}});
    page.querySelector('#utr-guide')?.addEventListener('click',()=>{const d=dialog(page,'<h2>Where to find your UTR</h2><p>Open the successful payment in your payment app’s transaction history. Copy its 12-digit UPI reference number and enter it here.</p><button type="button" data-close>Got it</button>');d.querySelector('[data-close]').onclick=()=>d.close();});
    submit.onclick=async()=>{if(submitting)return;order=current()||order;if(!valid()){tick();return;}submitting=true;submit.disabled=true;const utr=input.value;try{if(isYoupi){const fresh=await window.ColorWinYoupi.submit(order.id,utr);if(fresh){const snapshot=read(),index=snapshot.orders.findIndex(o=>o.id===fresh.id);if(index>=0){snapshot.orders[index]=fresh;write(snapshot);}order=fresh;gatewayState=fresh.gatewayStatus;tick();}}else await window.ColorWinOperations.wallet('submit_utr',{id:order.id,utr});const state=read(),saved=state.orders.find(o=>o.id===order.id);if(saved&&saved.status==='to be paid'){saved.status='pending';saved.utr=utr;saved.submittedAt=Date.now();write(state);}if(active?.page===page)active.allowLeave=true;toast('Submission successful');tick();window.ColorWinOperations.loadWallet().then(()=>{if(page.isConnected)tick();}).catch(()=>{});}catch(err){submitting=false;toast(err.message,true);update();}};
    page.querySelectorAll('[data-open-app]').forEach(b=>b.onclick=()=>{if(stopped()){tick();return;}if(b.dataset.openApp.startsWith('PhonePe Bank')){toast('Use your payment app to choose a supported bank card.');return;}location.href=payload(order);});
    const saveQr=()=>{if(stopped()){tick();toast('This order is no longer accepting payment.');return;}const canvas=qr.querySelector('canvas');if(!canvas){toast('QR unavailable',true);return;}const a=document.createElement('a');a.download=(order.number||order.id)+'-qr.png';a.href=canvas.toDataURL('image/png');a.click();};
    page.querySelector('#payment-save')?.addEventListener('click',saveQr);
    const requestCancel=()=>{order=current()||order;if(page.querySelector('.checkout-dialog,.checkout-cancel-sheet')||order.status!=='to be paid')return;cancel(page,order,{read,write,toast,onPaid:()=>input.focus(),onCancelled:()=>{if(active?.page===page)active.allowLeave=true;}});};
    active={page,route:location.hash.toLowerCase(),url:location.href,allowLeave:false,shouldBlock:()=>{const o=current();return o?.status==='to be paid'&&Date.now()<o.expiresAt;},requestCancel};
    const back=page.querySelector('.checkout-header>a:first-child');back.onclick=e=>{if(active?.page===page&&active.shouldBlock()){e.preventDefault();requestCancel();}};
    page.querySelector('.checkout-service')?.addEventListener('click',()=>{if(active?.page===page)active.allowLeave=true;});
    page.querySelector('#payment-cancel').onclick=requestCancel;
    if(order.status==='pending')status.textContent='UTR submitted. Pending payment verification.';
    else if(order.status==='cancelled')status.textContent='This order was cancelled.';
  }
  async function copy(value,toast){try{await navigator.clipboard.writeText(value);toast('Copied successfully');}catch{toast('Unable to copy. Please try again.',true);}}
  function cancel(page,order,{read,write,toast,onPaid,onCancelled}){
    const warning=dialog(page,'<h2>Cancel Transaction</h2><p>If you have successfully transferred funds, please do not cancel the transaction!</p><div class="cancel-confirm-actions"><button type="button" id="cancel-confirm">Confirm Cancellation</button><button type="button" id="cancel-paid">I have paid</button></div>');
    warning.querySelector('#cancel-paid').onclick=()=>{warning.close();onPaid();};
    warning.querySelector('#cancel-confirm').onclick=()=>{
      warning.close();const reasons=["I don't want to continue payment",'Want to use another payment method','Bank system is under maintenance','UPI payment error','Other reasons'];
      const d=dialog(page,'<h2>Cancel</h2><form id="cancel-form">'+reasons.map((r,i)=>'<label><input type="radio" name="reason" value="'+esc(r)+'" '+(i===0?'checked':'')+'><span>'+esc(r)+'</span></label>').join('')+'<textarea name="other" placeholder="Please fill in other reasons" aria-label="Other cancellation reason" maxlength="300"></textarea><button type="submit">Confirm Cancellation</button></form>','checkout-cancel-sheet');
      const form=d.querySelector('form'),other=form.elements.other;form.onchange=()=>{other.required=form.elements.reason.value==='Other reasons';};
      form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const reason=form.elements.reason.value==='Other reasons'?other.value.trim():form.elements.reason.value;if(!reason){other.focus();return;}const state=read(),saved=state.orders.find(o=>o.id===order.id);if(!saved||saved.status!=='to be paid'){d.close();toast('This order cannot be cancelled.',true);return;}try{const b=form.querySelector('[type=submit]');b.disabled=true;if(order.gatewayProvider==='youpi')await window.ColorWinYoupi.cancel(order.id,reason);else await window.ColorWinOperations.wallet('cancel_deposit',{id:order.id,reason});}catch(err){toast(err.message,true);form.querySelector('[type=submit]').disabled=false;return;}saved.status='cancelled';saved.cancelReason=reason;saved.cancelledAt=Date.now();write(state);onCancelled();d.close();toast('Deposit order cancelled');location.hash='#/deposit/history';};
    };
  }
  window.ColorWinCheckout={view,bind,maintenance,guardRoute};
})();


